import"./chunk-2NFLSA4Y.js";var i={uniformMotion:{theory:{concept:"[[Uniform rectilinear motion is motion along a straight line in which a body covers equal distances in any equal time intervals; its velocity is constant.]] The position of the body changes linearly with time, x = x\u2080 + v \xB7 t, so its position\u2013time graph is a straight line whose slope equals the velocity."},section:{definition:{title:"What is uniform motion?",text:"If a bicycle covers 5 m in the first second, it covers 5 m in every following second as well. [[Its speed does not grow or shrink, and its direction does not change.]]"},marks:{title:"Equal times, equal distances",text:"The dots on the road show where the bicycle was after every equal time interval. In uniform motion all gaps between the dots are the same. If the gaps grew or shrank, the speed would be changing \u2014 that is accelerated motion, the next topic."},speed:{title:"Speed = distance \xF7 time",text:"[[Speed is the distance covered divided by the time taken: v = s / t.]] In physics it is measured in metres per second (m/s). Cars use kilometres per hour: 1 m/s = 3.6 km/h, so 10 m/s is 36 km/h. Knowing two of the three quantities (s, v, t), you can always find the third."},graphs:{title:"Graphs of uniform motion",text:"[[The distance\u2013time graph is a straight sloping line: every second adds the same distance.]] The steeper the line, the greater the speed. The speed\u2013time graph is a horizontal line, because the speed does not change. The area under it (v \xD7 t) equals the distance covered."},example:{title:"In real life",text:"An escalator, a conveyor belt or a car on cruise control on a straight motorway move almost uniformly. Real motion is never perfectly uniform: a car has to speed up at the start and slow down at the end. Uniform motion is a simple model that describes the steady middle part well."},check:{title:"Check your understanding",text:"A cyclist rides at 5 m/s. How far does she go in 20 s? (100 m.) How long does a 100 m road take at 20 m/s? (5 s.) Which is faster: 20 m/s or 60 km/h? (20 m/s = 72 km/h.) Try each answer in the simulation."}},formula:{speed:"Speed: distance divided by time",distance:"Distance covered at constant speed",time:"Time needed to cover a distance",units:"Converting metres per second into kilometres per hour",position:"Position on the road: starting position plus the distance covered"},variable:{distance:"Distance covered",speed:"Speed (constant)",time:"Time",start:"Starting position (bicycle 2 starts d\u2080 ahead)"},assumption:{point:"Each bicycle is treated as a point \u2014 the front of its front wheel \u2014 so its size does not matter.",instant:"The bicycle has its full speed from the first moment and does not brake at the finish. Real bicycles and cars need time to speed up and slow down.",straight:"The road is straight and the bicycle never changes direction.",scale:"Bicycles are drawn larger than scale so that they stay visible on long roads. Their wheels turn so that they do not slip on the road, so the bigger the drawing, the slower they turn. A wheel that spins too fast to follow is drawn as a blurred disc."},param:{speed:"Speed",roadLength:"Distance to the finish",compare:"Second bicycle for comparison",speed2:"Speed of bicycle 2",headStart:"Head start of bicycle 2"},hint:{speed:"1 m/s = 3.6 km/h. A walker does about 1.5 m/s, a city car about 14 m/s (50 km/h).",compare:"Race two bicycles on parallel lanes. The race ends when the first bicycle reaches the finish.",headStart:"Bicycle 2 starts this many metres ahead of the start line."},preset:{walk:"Walking",bike:"Bicycle",city:"City car",highway:"Motorway"},measure:{distance:"Distance covered",speedKmh:"Speed in km/h",remaining:"Distance to the finish",position2:"Position of bicycle 2",gap:"Bicycle 1 ahead of bicycle 2 by",finishTime:"Time bicycle 1 needs to the finish",finishTime2:"Time bicycle 2 needs to the finish"},view:{start:"Start",finish:"Finish",marksEvery:"Dots: bicycle position every {dt}",finished:"Finish! Time: {time}",winner:"Bicycle {bike} wins in {time}",tie:"A tie! Both bicycles finish in {time}",timeLimit:"Time is up \u2014 the bicycle is too slow for this road"},graph:{position:"Distance against time",speed:"Speed against time"},challenge:{tenSeconds:{title:"Exactly 10 seconds",description:"Choose a speed so that the bicycle reaches the finish in exactly 10 s.",hint:"v = s / t: divide the distance to the finish by 10 s."},slow:{title:"Slow and steady",description:"Make the trip to the finish last at least one minute.",hint:"Lower the speed \u2014 how fast does a walker go?"},fast:{title:"Motorway speed",description:"Cover at least 100 m in 4 s or less.",hint:"100 m in 4 s needs 25 m/s \u2014 that is 90 km/h."},overtake:{title:"Catch up",description:"Give bicycle 2 a head start of at least 20 m and still let bicycle 1 win.",hint:"Bicycle 1 must be faster. The bigger the head start, the bigger the difference in speed it needs."},tie:{title:"Photo finish",description:"Choose different speeds and a head start so that both bicycles reach the finish at the same moment.",hint:"Both times must be equal: L / v\u2081 = (L \u2212 d\u2080) / v\u2082. Example: 100 m at 10 m/s and 60 m at 6 m/s."},kmh:{title:"54 km/h",description:"Ride to the finish at exactly 54 km/h.",hint:"Divide by 3.6 to get the speed in m/s."}}}},s={sim:i};export{s as default,i as sim};
